--
-- Table structure for table `news`
--

DROP TABLE IF EXISTS `news`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `news` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `wm_user_id` bigint NOT NULL COMMENT 'ä½œè€…',
  `channel_id` int NOT NULL COMMENT 'é¢‘é“',
  `title` varchar(60) NOT NULL COMMENT 'æ ‡é¢˜',
  `content` longtext NOT NULL COMMENT 'æ­£æ–‡ HTML',
  `cover_type` tinyint NOT NULL DEFAULT '0' COMMENT '0æ— å›¾ 1å•å›¾ 3ä¸‰å›¾',
  `cover_images` varchar(1000) DEFAULT NULL COMMENT 'å°é¢åœ°å€ï¼Œé€—å·åˆ†éš”ï¼ˆæŒ‡å‘ç´ æå›¾ç‰‡æŽ¥å£ï¼‰',
  `labels` varchar(200) DEFAULT NULL COMMENT 'æ ‡ç­¾ï¼Œé€—å·åˆ†éš”',
  `status` tinyint NOT NULL DEFAULT '0' COMMENT '0è‰ç¨¿ 1å¾…å®¡æ ¸ 2é€šè¿‡ 3é©³å›ž',
  `is_top` tinyint NOT NULL DEFAULT '0' COMMENT 'æ˜¯å¦ç½®é¡¶',
  `publish_time` datetime DEFAULT NULL,
  `views` int NOT NULL DEFAULT '0',
  `likes` int NOT NULL DEFAULT '0',
  `comments` int NOT NULL DEFAULT '0',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
